<script module lang="ts">
/**
 * A joined row of segments that always holds one value (`design/components/segmented-control.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/segmented-control.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext, onDestroy, setContext } from 'svelte'

import * as zag from '@zag-js/radio-group'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  joinSlot,
  normalizeProps,
  roveRadio,
  useDirection,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/segmented-control.module.css'

export type SegmentedControlSize = NonNullable<SegmentedControlProps['size']>

export interface SegmentedControlOption {
  value: string
  label: string
  icon?: IconRole
  disabled?: boolean
}

export interface SegmentedControlProps {
  defaultValue?: string
  /**
   * Disables the whole group. Use `disabled` in `options` for single options.
   */
  disabled?: boolean
  /**
   * The group's accessible name, because outside a form there is no FormField to name it.
   */
  label: string
  onChange?: (value: string) => void
  /**
   * Items render from data, because free-form children invite ad hoc layouts (Radio's law).
   */
  options: SegmentedControlOption[]
  /**
   * There is no `lg`, on purpose. A segmented control is an inline control used in toolbars,
   * page headers and filter rows next to `sm`/`md` controls. A form-sized single choice is
   * RadioGroup in a FormField, not this at 44px.
   */
  size?: 'sm' | 'md'
  value?: string
}
</script>

<script lang="ts">
let {
  defaultValue,
  disabled = false,
  label: labelOwn,
  onChange,
  options,
  size = 'md',
  value,
}: SegmentedControlProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const lent = getContext<string | undefined>('polymorph:identity')
const lender = getContext<{ element?: () => Element | null | undefined } | undefined>(
  'polymorph:borrowed',
)
setContext('polymorph:borrowed', undefined)
let track = $state<HTMLElement | null>(null)
const documentDirection = useDirection(() => track)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      value: value,
      defaultValue: defaultValue ?? options[0]?.value,
      disabled: disabled,
      onValueChange: (details) => {
        onChange?.(details.value ?? '')
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const stop = $derived(
  api.value ?? options.find((option) => !(disabled || option.disabled === true))?.value,
)
const effect1 = () => {
  lender && (lender.element = () => track)
}
watchEffect(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'SegmentedControl',
    element: () => track,
    state: () => ({
      value: api.value ?? null,
      options: options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      disabled: disabled,
    }),
    actions: {
      choose: { argument: 'id', run: (value) => value !== api.value && api.setValue(value) },
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={track}
    class={styles.track}
    role="radiogroup"
    aria-label={label}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-member={lent ?? 'segmented-control'}
    >{#each options as option (option.value)
      }<button
        class={styles.segment}
        type="button"
        role="radio"
        value={option.value}
        aria-checked={api.value === option.value}
        disabled={disabled || option.disabled === true}
        tabindex={(option.value === stop ? 0 : -1) as never}
        data-state={(api.value === option.value) ? 'checked' : 'unchecked'}
        data-disabled={(disabled || option.disabled === true) ? '' : undefined}
        onclick={() => { api.setValue(option.value) }}
        onkeydown={(event) => { event.key === 'Enter' ? event.preventDefault() : roveRadio(event, (next) => api.setValue(next)) }}
        >{#if api.value === option.value}<span class={styles.chip} data-state="checked"></span>{/if
        }{#if option.icon !== undefined
          }<span class={styles.glyph}><Icon name={option.icon} {size} /></span
        >{/if
        }<span class={styles.label}>{option.label}</span
      ></button
    >{/each
  }</div
>{/if
}{@render joined.end?.()}
